     1	using System;
     2	using UnityEngine;
     4	public class LightningComboProjectile : Projectile
     5	{
     6		private static GameObject prefab;
     8		public Sprite[] sprites;
    10		private Entity targetEntity;
    12		private bool targetHit;
    14		private int maxHitCount = 5;
    16		public float hitInterval = 0.1f;
    18		private int hitStopwatchID;
    20		private int curHitCount;
    22		public bool isEmpowered;
    24		private LightningShadow currentShadow;
    26		public FacingDirection facingDir;
    28		public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/LightningComboProjectile.prefab"));
    30		public override void Awake()
    31		{
    32			base.Awake();
    33			projectileSpriteRenderer.material.SetFloat("_PaletteIndex", 6f);
    34		}
    36		public override void Start()
    37		{
    38			base.Start();
    39			if (isEmpowered)
    40			{
    41				maxHitCount += 2;
    42				attackBox.ChangeAttackInfoLevel(2);
    43			}
    44			SetSprite();
    45			Attack attack = attackBox;
    46			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
    47			Attack attack2 = attackBox;
    48			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
    49		}
    51		private void SetSprite()
    52		{
    53			switch (facingDir)
    54			{
    55			case FacingDirection.Up:
    56				projectileSpriteRenderer.sprite = sprites[0];
    57				projectileSpriteRenderer.transform.localEulerAngles = Vector3.zero;
    58				projectileSpriteRenderer.transform.localPosition = new Vector3(0f, -0.75f, 0f);
    59				break;
    60			case FacingDirection.Right:
    61				projectileSpriteRenderer.sprite = sprites[1];
    62				projectileSpriteRenderer.transform.localEulerAngles = Vector3.zero;
    63				projectileSpriteRenderer.transform.localPosition = new Vector3(0f, -0.75f, 0f);
    64				break;
    65			case FacingDirection.Down:
    66				projectileSpriteRenderer.sprite = sprites[2];
    67				projectileSpriteRenderer.transform.localEulerAngles = Vector3.zero;
    68				projectileSpriteRenderer.transform.localPosition = new Vector3(0f, -0.75f, 0f);
    69				break;
    70			case FacingDirection.Left:
    71				projectileSpriteRenderer.sprite = sprites[1];
    72				projectileSpriteRenderer.transform.localScale = Globals.ScaleVecFlipX;
    73				projectileSpriteRenderer.transform.localEulerAngles = Vector3.zero;
    74				projectileSpriteRenderer.transform.localPosition = new Vector3(0f, -0.75f, 0f);
    75				break;
    76			}
    77		}
    79		public override void ResetProjectile()
    80		{
    81			Attack attack = attackBox;
    82			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
    83			if (!targetHit || targetEntity == null)
    84			{
    85				base.ResetProjectile();
    86				string audioID = "BallLightningEnd";
    87				Vector2? soundOrigin = transform.position;
    88				float standardPitchRange = SoundManager.StandardPitchRange;
    89				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
    90				PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(5, transform.position);
    91			}
    92		}
    94		private void OnTargetHit(Entity hitEntity)
    95		{
    96			if (!targetHit && !(hitEntity == null) && hitEntity is Enemy && !(hitEntity.hurtBoxTransform == null))
    97			{
    98				targetHit = true;
    99				targetEntity = hitEntity;
   100				wallCollider.enabled = false;
   101				attackBox.collider.enabled = false;
   102				hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, maxHitCount);
   103				rigidbody2D.velocity = Vector2.zero;
   104				projectileSpriteRenderer.enabled = false;
   105				for (int i = 0; i < maxHitCount; i++)
   106				{
   107					PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(4, targetEntity.hurtBoxTransform.position);
   108					CreateShadow();
   109					curHitCount++;
   110				}
   111				base.ResetProjectile();
   112			}
   113		}
   115		private void CreateShadow()
   116		{
   117			currentShadow = Globals.ChaosInst<LightningShadow>(LightningShadow.Prefab, null, targetEntity.hurtBoxTransform.position + (Vector3)Globals.GetCirclePositionVector(maxHitCount, curHitCount) * 3f);
   118			currentShadow.Initialize(givenEmp: false, attackBox.atkInfo.skillCategory, attackBox.atkInfo.skillID, targetEntity.hurtBoxTransform, (targetEntity.hurtBoxTransform.position - (Vector3)Globals.GetCirclePositionVector(maxHitCount, curHitCount)).normalized, 0.1f * (float)curHitCount, givenUseBurst: false, givenReverseSpawnAnim: true);
   119		}
   120	}
=========== LightningXStrike
     1	using UnityEngine;
     3	public class LightningXStrike : Projectile
     4	{
     5		private static GameObject prefab;
     7		private LightningXStrike otherXStrike;
     9		private Vector2 mainVec;
    11		private Vector2 altVec;
    13		private bool useMainVec = true;
    15		private bool useBurst;
    17		private int burstLevel = 2;
    19		private float burstScale = 1f;
    21		private Vector2 kbVector;
    23		private ChaosQuickStopwatch flipStopwatch = new ChaosQuickStopwatch();
    25		private Vector2 currentPosition;
    27		private int maxBounceCount = 4;
    29		private int bounceCounter;
    31		private bool resetQueued;
    33		private bool resetExec;
    35		public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/LightningXStrikeObject.prefab"));
    37		public void InitStrike(LightningXStrike givenOther, Vector2 givenMain, Vector2 givenAlt, float givenTime, Vector2 givenKB, bool givenBurst = false, int givenLevel = 2, float givenScale = 1f)
    38		{
    39			otherXStrike = givenOther;
    40			moveVector = givenMain;
    41			mainVec = givenMain;
    42			altVec = givenAlt;
    43			flipStopwatch.SetDelay(givenTime);
    44			flyTime = givenTime * ((float)maxBounceCount * 1.95f);
    45			useBurst = givenBurst;
    46			burstLevel = givenLevel;
    47			burstScale = givenScale;
    48			kbVector = givenKB;
    49		}
    51		public override void Start()
    52		{
    53			base.Start();
    54			PlayParticleEffect();
    55			flipStopwatch.IsRunning = true;
    56		}
    58		public override void FixedUpdate()
    59		{
    60			base.FixedUpdate();
    61			if (otherXStrike == null)
    62			{
    63				resetExec = true;
    64				ResetProjectile();
    65			}
    66			else
    67			{
    68				if (flipStopwatch.IsRunning)
    69				{
    70					return;
    71				}
    72				flipStopwatch.IsRunning = true;
    73				useMainVec = !useMainVec;
    74				moveVector = ((!useMainVec) ? altVec : mainVec);
    75				SoundManager.PlayAudioWithDistance("ThunderKnock", transform.position);
    76				if (useMainVec)
    77				{
    78					PlayParticleEffect();
    79					return;
    80				}
    81				bounceCounter++;
    82				if (useBurst)
    83				{
    84					CreateBurst();
    85				}
    86				else
