68				parent.anim.Play("Charging", -1, 0f);
71			public override void ExecuteSkill()
73				if (firstWaveSpawned && !castAnimPlayed && !castAnimTimer.IsRunning)
75					parent.anim.Play("Cast", -1, 0f);
76					castAnimPlayed = true;
77					CameraController.ShakeCamera(0.3f);
78					DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
79					int particleCount = 20;
80					float z = Globals.GetRotationVector(-targetVector).z;
81					Vector3? emitPosition = parent.transform.position;
82					poolItem.EmitDirBurst(particleCount, z, -1f, -1f, -1f, emitPosition);
84				else if (firstWaveSpawned && castAnimPlayed && parent.anim.AnimPlayed(0.4f))
86					parent.anim.Play("Charging", -1, 0f);
88				switch (ChaosStopwatch.CheckInterval(waveStopwatchID))
90				case StopwatchState.Ready:
91					if (!FireMinions())
93						base.ExecuteSkill();
94						break;
96					if (!firstWaveSpawned)
98						firstWaveSpawned = true;
100					castAnimTimer.IsRunning = true;
101					castAnimPlayed = false;
102					break;
103				case StopwatchState.Done:
104					if (castAnimPlayed && parent.anim.AnimPlayed())
106						base.ExecuteSkill();
108					break;
112			private bool FireMinions()
114				currentMinionCount = parent.orbChList.Count;
115				if (currentMinionCount == 0 || parent.UpdateTargetInfo() == null)
117					return false;
119				halfCount = (int)((float)currentMinionCount * 0.5f);
120				UpdateTargetVector();
121				middlePosition = (Vector2)parent.transform.position + targetVector;
122				perpendVec = Globals.GetPerpendicular(targetVector) * 1.25f;
