152						currentOC.transform.position = Globals.GetLinecastVector(middlePosition, middlePosition + Globals.GetCirclePositionVector(currentMinionCount, i) * 6f, ChaosCollisions.layerAllWall);
153						currentOC.movement.EndMovement();
154						CreatePortalEffect(currentOC);
