300						spawnPosition = Globals.GetLinecastVector(currentPosition, currentPosition + Globals.GetRotatedCircleVector(currentSpawnCount, j, Vector2.down) * 3f, ChaosCollisions.layerAllWallAndObst);
301						SummonOrbFamiliar(EName.OrbRevolveFamiliar, spawnPosition, rvList);
